"""E3 figures for the slides, regenerated by `make figures`. No LLM and no network.

fig6_e3_arms.pdf / .png    plausible-fix rate per repair arm (R1, R2, R3) per model, standard variant, 95% Wilson
                           intervals. Uses `analysis.rq4_repair.replay_runs`, the replay `make repair-eval` uses, so it
                           follows the caches (`eval/llm_cache/`) as they grow. The title carries the actual n.
fig7_retrieval.pdf / .png  localization hit@3 for L1-L5, standard vs hard variant, read from
                           `paper/generated/rq5_retrieval.md` (written by `make rag-eval`).

Skips with a warning when matplotlib is absent, like `rq2_figures`.
"""

from __future__ import annotations

import json
import math
import re
import sys
from pathlib import Path

OUT = Path("paper/generated")
RQ5_MD = OUT / "rq5_retrieval.md"
ARM_LABELS = {"R1": "R1 whole repo", "R2": "R2 change-aware", "R3": "R3 R2 + retries"}
COLORS = ["#0072B2", "#E69F00", "#009E73", "#CC79A7", "#56B4E9"]   # Okabe-Ito, colour-blind safe
Z95 = 1.959963984540054


def wilson(k: int, n: int, z: float = Z95) -> tuple[float, float]:
    """Wilson score interval for `k` successes in `n` trials; `(0, 1)` when `n` is 0."""
    if n == 0:
        return 0.0, 1.0
    p = k / n
    den = 1 + z * z / n
    centre = (p + z * z / (2 * n)) / den
    half = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / den
    return max(0.0, centre - half), min(1.0, centre + half)


def arm_counts(recs: list[dict], arms: tuple[str, ...] = ("R1", "R2", "R3")) -> dict[str, tuple[int, int]]:
    """`{arm: (plausible fixes, tasks)}` over the records that have the arm."""
    out = {}
    for a in arms:
        xs = [r[a]["accepted"] for r in recs if a in r]
        out[a] = (sum(1 for x in xs if x), len(xs))
    return out


def model_label(model: str) -> str:
    return model.split("/")[-1]


def title_n(counts: dict[str, dict[str, tuple[int, int]]]) -> str:
    """`n = 47` when every model and arm has the same n, else `n = 47 (gpt-oss-120b), 45 (gpt-oss-20b)`."""
    per_model = {m: max((n for _, n in c.values()), default=0) for m, c in counts.items()}
    if len(set(per_model.values())) == 1:
        return f"n = {next(iter(per_model.values()))} per model"
    return "n = " + ", ".join(f"{n} ({model_label(m).removeprefix('gpt-oss-')})" for m, n in per_model.items())


def fig6(plt, meta_pdf: dict, counts: dict[str, dict[str, tuple[int, int]]], tag: str) -> None:
    models = list(counts)
    arms = ("R1", "R2", "R3")
    fig, ax = plt.subplots(figsize=(8, 4.6))
    width = 0.26
    for i, arm in enumerate(arms):
        xs, ys, lo, hi = [], [], [], []
        for j, m in enumerate(models):
            k, n = counts[m][arm]
            if n == 0:
                continue
            a, b = wilson(k, n)
            xs.append(j + (i - 1) * width)
            ys.append(100 * k / n)
            lo.append(100 * k / n - 100 * a)
            hi.append(100 * b - 100 * k / n)
        ax.bar(xs, ys, width, yerr=[lo, hi], capsize=3, color=COLORS[i], edgecolor="black", linewidth=0.6,
               label=ARM_LABELS[arm], error_kw={"elinewidth": 1.1})
        for x, y, h in zip(xs, ys, hi):
            ax.text(x, y + h + 1.5, f"{y:.0f}", ha="center", va="bottom", fontsize=8)
    ax.set_xticks(range(len(models)))
    ax.set_xticklabels([f"{model_label(m)}\nn = {max(n for _, n in counts[m].values())}" for m in models])
    ax.set_ylabel("plausible fix: full suite green (%)")
    ax.set_ylim(0, 105)
    ax.set_title(f"E3 plausible-fix rate per arm (interim, {title_n(counts)})", fontsize=11)
    ax.legend(fontsize=8, loc="upper right", ncol=3, frameon=False)
    ax.spines[["top", "right"]].set_visible(False)
    ax.text(0, -0.2, "Standard variant. Bars: share of tasks with a plausible fix. Whiskers: 95% Wilson interval. " + tag,
            transform=ax.transAxes, fontsize=7, color="#444444")
    fig.tight_layout()
    fig.savefig(OUT / "fig6_e3_arms.pdf", metadata=meta_pdf)
    fig.savefig(OUT / "fig6_e3_arms.png", dpi=200, metadata={"Software": None})
    plt.close(fig)


ROW = re.compile(r"^\| (L\d)\b[^|]*\|[^|]*\| (\d+)/(\d+) \([\d.]+%\) \|")


def parse_hit3(md: str) -> dict[str, dict[str, tuple[int, int]]]:
    """`{variant: {L1..L5: (hit@3 count, n)}}` from the localization tables of `rq5_retrieval.md`."""
    out: dict[str, dict[str, tuple[int, int]]] = {}
    variant = None
    for ln in md.splitlines():
        if ln.startswith("## ") and not ln.startswith("## Localization"):
            variant = None
        m = re.match(r"### (Standard|Hard) variant", ln)
        if m:
            variant = m.group(1).lower()
            out[variant] = {}
        elif variant and (row := ROW.match(ln)):
            out[variant][row.group(1)] = (int(row.group(2)), int(row.group(3)))
    return out


def fig7(plt, meta_pdf: dict, hit3: dict[str, dict[str, tuple[int, int]]]) -> None:
    modes = ["L1", "L2", "L3", "L4", "L5"]
    names = {"L1": "L1 BM25\nwhole repo", "L2": "L2 dense\nwhole repo", "L3": "L3 hybrid\nwhole repo",
             "L4": "L4 BM25\ndiff functions", "L5": "L5 hybrid\ndiff functions"}
    fig, ax = plt.subplots(figsize=(8, 4.6))
    width = 0.36
    for i, (variant, color) in enumerate((("standard", "#0072B2"), ("hard", "#D55E00"))):
        xs = [j + (i - 0.5) * width for j in range(len(modes))]
        vals = [hit3[variant][m] for m in modes]
        ys = [100 * k / n for k, n in vals]
        ax.bar(xs, ys, width, color=color, edgecolor="black", linewidth=0.6, label=f"{variant} (n = {vals[0][1]})")
        for x, y, (k, n) in zip(xs, ys, vals):
            ax.text(x, y + 1.5, f"{k}/{n}", ha="center", va="bottom", fontsize=7.5)
    ax.set_xticks(range(len(modes)))
    ax.set_xticklabels([names[m] for m in modes], fontsize=8)
    ax.set_ylabel("seeded function in the top 3 chunks, hit@3 (%)")
    ax.set_ylim(0, 110)
    ax.set_title("Localization retrieval, standard vs hard variant (exploratory, no model)", fontsize=11)
    ax.legend(fontsize=8, loc="upper left", frameon=False)
    ax.spines[["top", "right"]].set_visible(False)
    fig.tight_layout()
    fig.savefig(OUT / "fig7_retrieval.pdf", metadata=meta_pdf)
    fig.savefig(OUT / "fig7_retrieval.png", dpi=200, metadata={"Software": None})
    plt.close(fig)


def main() -> int:
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
    except ImportError:
        print("WARNING: matplotlib is not installed; skipping fig6-fig7.")
        return 0
    OUT.mkdir(parents=True, exist_ok=True)
    meta_pdf = {"CreationDate": None}

    from analysis import rq4_repair as rq4

    pins = json.loads(rq4.REPOS_JSON.read_text())
    _, runs, _ = rq4.replay_runs(pins)
    counts = {model: arm_counts(recs) for (model, variant), recs in runs.items() if variant == "standard" and recs}
    if not counts:
        print("no cached E3 runs under eval/llm_cache/; skipping fig6", file=sys.stderr)
        return 1
    fig6(plt, meta_pdf, counts, "Replayed from eval/llm_cache/.")
    print("Generated fig6_e3_arms.pdf/.png: " + "; ".join(
        f"{model_label(m)} " + " ".join(f"{a} {k}/{n}" for a, (k, n) in c.items()) for m, c in counts.items()))

    if not RQ5_MD.exists():
        print(f"{RQ5_MD} missing: run `make rag-eval` first", file=sys.stderr)
        return 1
    hit3 = parse_hit3(RQ5_MD.read_text(encoding="utf-8"))
    if set(hit3) != {"standard", "hard"} or any(len(v) != 5 for v in hit3.values()):
        print(f"could not read L1-L5 for both variants from {RQ5_MD}: {hit3}", file=sys.stderr)
        return 1
    fig7(plt, meta_pdf, hit3)
    print("Generated fig7_retrieval.pdf/.png: " + "; ".join(
        f"{v} " + " ".join(f"{m} {k}/{n}" for m, (k, n) in h.items()) for v, h in hit3.items()))
    return 0


if __name__ == "__main__":
    sys.exit(main())
